        address user = address(0x1234);
        // Fund user and deposit 1 ether into the contract
        vm.deal(user, 5 ether);
        vm.prank(user);
        c.Put{value: 1 ether}(0); // unlockTime = block.timestamp
        // Warp past unlock time so Collect is allowed
        vm.warp(block.timestamp + 1);
        // Attempt to collect 1 ether; the user contract will reenter via fallback
        // The reference contract reverts the reentrant call, so balance stays 0
        // The buggy contract allows reentrancy, so Put is called again, adding 1 ether
        // We use a try/catch to capture whether the outer Collect reverts
        bool ok;
        vm.prank(user);
        try c.Collect(1 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference contract reverts due to nonReentrant, so ok is false, and balance is 0.
        // The buggy contract does not revert, so ok is true, and balance becomes 1 ether.
        // We assert that ok is false (reference behavior). The bug will fail this assertion.
        assertTrue(!ok, "Reference reverts on reentrant Collect");
    }
}

