pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);

        // First call to Collect(0 ether) will revert because balance is 0 < MinSum (1 ether)
        vm.prank(alice);
        bool revert1;
        try c.Collect(0 ether) { revert1 = false; } catch { revert1 = true; }

        // Second call to Collect(0 ether) after revert – should also revert on reference,
        // but on buggy version the locked_ was never reset, so the require(!locked_) will fail,
        // causing revert; however our assertion must capture that the reference resets locked_,
        // allowing the second call to proceed (if balance condition were met) but here balance is still 0,
        // so both revert – we need a scenario where the second call would succeed if locked_ resets.
        // Let's adjust: first make a Put to get balance >= MinSum and unlock time past.

        // Reset: deploy fresh
        c = new C(address(this));
        vm.deal(alice, 2 ether);
        vm.warp(1000);

        // Put 1 ether so balance = 1 ether = MinSum, unlockTime = block.timestamp
        vm.prank(alice);
        c.Put{value: 1 ether}(800); // unlockTime = max(800, 1000) = 1000

        // Now Collect(1 ether) succeeds on reference, but first call from another sender would fail
        // Actually let's use two different callers to see the effect
        address bob = address(0x5678);
        vm.deal(bob, 1 ether);
        vm.prank(bob);
        c.Put{value: 1 ether}(900); // unlockTime = max(900, 1000) = 1000

        // Now both alice and bob have balance = 1 ether, unlockTime = 1000
        // Alice calls Collect(1 ether) – succeeds on reference, resets locked_
        // Bob calls Collect(1 ether) – should succeed on reference (locked_ reset)
        // On buggy version, Alice's call succeeds but leaves locked_ = true,
        // so Bob's call will revert due to require(!locked_)

        vm.warp(1001); // past unlock time

        vm.prank(alice);
        bool ok1;
        try c.Collect(1 ether) { ok1 = true; } catch { ok1 = false; }

        vm.prank(bob);
        bool ok2;
        try c.Collect(1 ether) { ok2 = true; } catch { ok2 = false; }

        // Reference: both succeed => ok1 == true, ok2 == true
        // Bug: first succeeds, second reverts => ok1 == true, ok2 == false
        assertTrue(ok1 == true && ok2 == true, "Second collect should succeed on reference");
        // But note: we want assertion that reference holds and bug breaks.
        // Here reference: ok2 == true; bug: ok2 == false
        // So a single assertion: assertTrue(ok2); – reference passes, bug fails.
        assertTrue(ok2);
    }
}

